        if (refused(result) && !declared(code(result))) {
            skip("$what was refused by a rule of the application: " + answer(result))
        }
        Assertions.fail<Unit>("$what failed: " + answer(result))
    }

    /** Whether a refusal is one the model declares: a field's constraint (invalid), an invariant, a lifecycle. */
    protected fun declared(code: String?): Boolean =
        code == "invalid" || (code != null && (code.startsWith("invariant.") || code.startsWith("state.")))

    /** The row was made: 2xx (refused as succeeded says). */
    protected fun assertCreated(result: MvcResult) = succeeded(result, "the row")

    /** Aborts the test with the reason - in the report, and in the output, which a build's XML report keeps. */
    protected fun skip(reason: String) {
        println("[contract test skipped] " + reason)
        Assumptions.abort<Unit>(reason)
    }

    /** Refused with this status and the problem's code. */
    protected fun assertRefused(result: MvcResult, status: Int, expected: String) {
        Assertions.assertEquals(status, result.response.status) { "expected $status $expected: " + answer(result) }
        Assertions.assertEquals(expected, code(result)) { answer(result) }
    }

    /** Refused (400) for this field, with this constraint's code: NotNull, Size, Min ... */
    protected fun assertFieldError(result: MvcResult, field: String, code: String) {
        Assertions.assertEquals(400, result.response.status) { "expected 400 $field $code: " + answer(result) }
        for (error in fieldErrors(result)) {
            if (field == error["field"] && code == error["code"]) return
        }
        Assertions.fail<Unit>("expected the field error $field $code: " + answer(result))
    }

    /** The answer shows this value for the field. */
    protected fun assertValue(result: MvcResult, field: String, expected: Any?) {
        Assertions.assertEquals(expected.toString(), value(result, field).toString()) { "$field: " + answer(result) }
    }

    /** The answer shows the field set: a @stamp written by the move. */
    protected fun assertStamped(result: MvcResult, field: String) {
        Assertions.assertNotNull(value(result, field)) { "$field is not set: " + answer(result) }
    }

    /** A field of the answer, or null. */
    protected fun value(result: MvcResult, field: String): Any? =
        try {
            JsonPath.read<Any?>(body(result), "\$['$field']")
        } catch (notThere: RuntimeException) {
            null
        }

    /** The problem's code, or null. */
    protected fun code(result: MvcResult): String? = value(result, "code")?.toString()

    private fun fieldErrors(result: MvcResult): List<Map<String, Any?>> =
        try {
            JsonPath.read<List<Map<String, Any?>>>(body(result), "\$.fieldErrors")
        } catch (none: RuntimeException) {
            emptyList()
        }

    protected fun body(result: MvcResult): String = result.response.getContentAsString(StandardCharsets.UTF_8)

    /** The status and the body, for a message. */
    protected fun answer(result: MvcResult): String = "${result.response.status} " + body(result)

    protected fun ok(result: MvcResult): Boolean = result.response.status in 200..299

    protected fun refused(result: MvcResult): Boolean = result.response.status in 400..499

    // ---- values

    /** Text of exactly this length, unique in the run. */
    protected fun text(length: Int): String {
        val unique = java.lang.Long.toString(SEQUENCE.incrementAndGet(), 36)
        if (unique.length >= length) return unique.substring(unique.length - length)
        return "0".repeat(length - unique.length) + unique
    }

    /** An email address of exactly this length, unique in the run. */
    protected fun email(length: Int): String {
        if (length < 6) return text(length)
        val local = text(minOf(64, length - 5))
        val rest = length - local.length - 1
        val domain = StringBuilder("io")
        while (domain.length < rest) {
            val room = rest - domain.length - 1
            val label = if (room > 63) (if (room - 64 >= 1) 63 else 62) else room
            domain.insert(0, "x".repeat(label) + ".")
        }
        return "$local@$domain"
    }

    protected fun num(value: String): BigDecimal = BigDecimal(value)

    /** A number of its own for each row: from the first, in whole steps, within as many as the bounds hold. */
    protected fun serial(first: String, span: Long): BigDecimal =
        BigDecimal(first).add(BigDecimal.valueOf(SEQUENCE.incrementAndGet() % span))

    /**
     * The pattern's value, of its own for each row: each position given an alphabet takes one of
     * its characters (each was checked against the pattern when the test was written).
     */
    protected fun vary(sample: String, vararg alphabets: String): String {
        var n = SEQUENCE.incrementAndGet()
        val text = sample.toCharArray()
        var i = alphabets.size - 1
        while (i >= 0 && n > 0) {
            val alphabet = alphabets[i]
            if (alphabet.isNotEmpty()) {
                text[i] = alphabet[(n % alphabet.length).toInt()]
                n /= alphabet.length
            }
            i--
        }
        return String(text)
    }

    /** A JSON object: name, value, name, value ... */
    protected fun obj(vararg namesAndValues: Any?): MutableMap<String, Any?> {
        val obj = LinkedHashMap<String, Any?>()
        var i = 0
        while (i + 1 < namesAndValues.size) {
            obj[namesAndValues[i] as String] = namesAndValues[i + 1]
            i += 2
        }
        return obj
    }

    protected fun list(vararg items: Any?): MutableList<Any?> = items.toMutableList()

    /** The body with one field set - or sent as null. */
    protected fun withValue(body: MutableMap<String, Any?>, field: String, value: Any?): MutableMap<String, Any?> {
        body[field] = value
        return body
    }

    /** The value as JSON: maps, lists, text, numbers, booleans and null. */
    protected fun json(value: Any?): String = when (value) {
        null -> "null"
        is BigDecimal -> value.toPlainString()
        is Number, is Boolean -> value.toString()
        is Map<*, *> -> value.entries.joinToString(",", "{", "}") { json(it.key.toString()) + ":" + json(it.value) }
        is Collection<*> -> value.joinToString(",", "[", "]") { json(it) }
        else -> {
            val text = StringBuilder("\"")
            for (ch in value.toString()) {
                when {
                    ch == '"' || ch == '\\' -> text.append('\\').append(ch)
                    ch < ' ' -> text.append(String.format("\\u%04x", ch.code))
                    else -> text.append(ch)
                }
            }
            text.append('"').toString()
        }
    }
}
